-- Phase 4C: reusable vendor directory and auditable booking-service coordination.
CREATE TABLE public.event_vendors (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), vendor_name TEXT NOT NULL CHECK(char_length(btrim(vendor_name)) BETWEEN 1 AND 200), category TEXT NOT NULL CHECK(char_length(btrim(category)) BETWEEN 1 AND 100), contact_person TEXT CHECK(contact_person IS NULL OR char_length(btrim(contact_person))<=150), mobile TEXT CHECK(mobile IS NULL OR char_length(btrim(mobile))<=40), email TEXT CHECK(email IS NULL OR char_length(btrim(email))<=320), location TEXT CHECK(location IS NULL OR char_length(btrim(location))<=150), address TEXT CHECK(address IS NULL OR char_length(address)<=1000), description TEXT CHECK(description IS NULL OR char_length(description)<=4000), is_active BOOLEAN NOT NULL DEFAULT true, internal_notes TEXT CHECK(internal_notes IS NULL OR char_length(internal_notes)<=4000), created_by UUID REFERENCES public.admins(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.event_vendor_assignments (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), booking_id UUID NOT NULL REFERENCES public.celebration_bookings(id) ON DELETE CASCADE, booking_service_id UUID NOT NULL REFERENCES public.celebration_booking_services(id) ON DELETE RESTRICT, vendor_id UUID NOT NULL REFERENCES public.event_vendors(id) ON DELETE RESTRICT, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','declined','cancelled')), agreed_cost NUMERIC(12,2) CHECK(agreed_cost IS NULL OR agreed_cost>=0), currency TEXT NOT NULL DEFAULT 'INR' CHECK(currency='INR'), scheduled_date DATE, requirements TEXT CHECK(requirements IS NULL OR char_length(requirements)<=4000), internal_notes TEXT CHECK(internal_notes IS NULL OR char_length(internal_notes)<=4000), confirmed_at TIMESTAMPTZ, confirmed_by UUID REFERENCES public.admins(id) ON DELETE SET NULL, created_by UUID REFERENCES public.admins(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), lock_version INTEGER NOT NULL DEFAULT 1, CHECK((status='confirmed')=(confirmed_at IS NOT NULL)), CHECK((status='confirmed')=(confirmed_by IS NOT NULL)));
CREATE UNIQUE INDEX event_vendor_assignments_active_unique ON public.event_vendor_assignments(booking_service_id,vendor_id) WHERE status IN ('pending','confirmed');
CREATE TABLE public.event_vendor_assignment_activities (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), assignment_id UUID NOT NULL REFERENCES public.event_vendor_assignments(id) ON DELETE CASCADE, event_type TEXT NOT NULL CHECK(event_type IN ('created','updated','confirmed','declined','cancelled')), actor_id UUID REFERENCES public.admins(id) ON DELETE SET NULL, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX event_vendor_assignments_booking_idx ON public.event_vendor_assignments(booking_id,booking_service_id); CREATE INDEX event_vendor_assignment_activities_idx ON public.event_vendor_assignment_activities(assignment_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.set_event_vendor_updated_at() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.set_event_vendor_assignment_updated_at() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now(); NEW.lock_version=OLD.lock_version+1; RETURN NEW; END $$;
CREATE TRIGGER event_vendors_updated_at BEFORE UPDATE ON public.event_vendors FOR EACH ROW EXECUTE FUNCTION public.set_event_vendor_updated_at(); CREATE TRIGGER event_vendor_assignments_updated_at BEFORE UPDATE ON public.event_vendor_assignments FOR EACH ROW EXECUTE FUNCTION public.set_event_vendor_assignment_updated_at();
ALTER TABLE public.event_vendors ENABLE ROW LEVEL SECURITY; ALTER TABLE public.event_vendor_assignments ENABLE ROW LEVEL SECURITY; ALTER TABLE public.event_vendor_assignment_activities ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.event_vendors,public.event_vendor_assignments,public.event_vendor_assignment_activities FROM PUBLIC,anon,authenticated; GRANT ALL ON public.event_vendors,public.event_vendor_assignments,public.event_vendor_assignment_activities TO service_role;
CREATE OR REPLACE FUNCTION public.create_admin_vendor_assignment(p_booking_id UUID,p_booking_service_id UUID,p_vendor_id UUID,p_agreed_cost NUMERIC,p_scheduled_date DATE,p_requirements TEXT,p_internal_notes TEXT,p_admin_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE v_id UUID; v_status TEXT; BEGIN SELECT status INTO v_status FROM public.celebration_bookings WHERE id=p_booking_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Booking not found' USING ERRCODE='P0002'; END IF; IF v_status NOT IN ('confirmed','planning','ready') THEN RAISE EXCEPTION 'Vendor assignments are only permitted for confirmed, planning, or ready bookings' USING ERRCODE='22023'; END IF; IF NOT EXISTS(SELECT 1 FROM public.celebration_booking_services WHERE id=p_booking_service_id AND booking_id=p_booking_id) THEN RAISE EXCEPTION 'Booking service does not belong to this booking' USING ERRCODE='22023'; END IF; IF NOT EXISTS(SELECT 1 FROM public.event_vendors WHERE id=p_vendor_id AND is_active) THEN RAISE EXCEPTION 'Vendor is not active' USING ERRCODE='22023'; END IF; IF p_agreed_cost IS NOT NULL AND p_agreed_cost<0 THEN RAISE EXCEPTION 'Agreed cost cannot be negative' USING ERRCODE='22023'; END IF; INSERT INTO public.event_vendor_assignments(booking_id,booking_service_id,vendor_id,agreed_cost,scheduled_date,requirements,internal_notes,created_by) VALUES(p_booking_id,p_booking_service_id,p_vendor_id,p_agreed_cost,p_scheduled_date,NULLIF(btrim(p_requirements),''),NULLIF(btrim(p_internal_notes),''),p_admin_id) RETURNING id INTO v_id; INSERT INTO public.event_vendor_assignment_activities(assignment_id,event_type,actor_id,metadata) VALUES(v_id,'created',p_admin_id,jsonb_build_object('to',jsonb_build_object('vendor_id',p_vendor_id,'agreed_cost',p_agreed_cost,'scheduled_date',p_scheduled_date))); RETURN v_id; END $$;
CREATE OR REPLACE FUNCTION public.update_admin_vendor_assignment(p_assignment_id UUID,p_agreed_cost NUMERIC,p_scheduled_date DATE,p_requirements TEXT,p_internal_notes TEXT,p_expected_lock_version INTEGER,p_admin_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE v public.event_vendor_assignments%ROWTYPE; v_status TEXT; BEGIN SELECT * INTO v FROM public.event_vendor_assignments WHERE id=p_assignment_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Vendor assignment not found' USING ERRCODE='P0002'; END IF; IF v.lock_version<>p_expected_lock_version THEN RAISE EXCEPTION 'Vendor assignment was updated by another administrator' USING ERRCODE='40001'; END IF; SELECT status INTO v_status FROM public.celebration_bookings WHERE id=v.booking_id; IF v_status NOT IN ('confirmed','planning','ready') OR v.status<>'pending' THEN RAISE EXCEPTION 'Only pending assignments on active bookings may be edited' USING ERRCODE='22023'; END IF; IF p_agreed_cost IS NOT NULL AND p_agreed_cost<0 THEN RAISE EXCEPTION 'Agreed cost cannot be negative' USING ERRCODE='22023'; END IF; UPDATE public.event_vendor_assignments SET agreed_cost=p_agreed_cost,scheduled_date=p_scheduled_date,requirements=NULLIF(btrim(p_requirements),''),internal_notes=NULLIF(btrim(p_internal_notes),'') WHERE id=v.id; INSERT INTO public.event_vendor_assignment_activities(assignment_id,event_type,actor_id,metadata) VALUES(v.id,'updated',p_admin_id,jsonb_build_object('from',jsonb_build_object('agreed_cost',v.agreed_cost,'scheduled_date',v.scheduled_date,'requirements',v.requirements,'internal_notes',v.internal_notes),'to',jsonb_build_object('agreed_cost',p_agreed_cost,'scheduled_date',p_scheduled_date,'requirements',NULLIF(btrim(p_requirements),''),'internal_notes',NULLIF(btrim(p_internal_notes),'')))); RETURN v.id; END $$;
CREATE OR REPLACE FUNCTION public.transition_admin_vendor_assignment(p_assignment_id UUID,p_to_status TEXT,p_expected_lock_version INTEGER,p_admin_id UUID) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE v public.event_vendor_assignments%ROWTYPE; v_booking TEXT; BEGIN SELECT * INTO v FROM public.event_vendor_assignments WHERE id=p_assignment_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Vendor assignment not found' USING ERRCODE='P0002'; END IF; IF v.lock_version<>p_expected_lock_version THEN RAISE EXCEPTION 'Vendor assignment was updated by another administrator' USING ERRCODE='40001'; END IF; SELECT status INTO v_booking FROM public.celebration_bookings WHERE id=v.booking_id; IF v_booking NOT IN ('confirmed','planning','ready') THEN RAISE EXCEPTION 'Vendor assignments are read-only for this booking' USING ERRCODE='22023'; END IF; IF (v.status='pending' AND p_to_status NOT IN ('confirmed','declined','cancelled')) OR (v.status='confirmed' AND p_to_status<>'cancelled') OR v.status IN ('declined','cancelled') THEN RAISE EXCEPTION 'Assignment status transition is not allowed' USING ERRCODE='22023'; END IF; UPDATE public.event_vendor_assignments SET status=p_to_status,confirmed_at=CASE WHEN p_to_status='confirmed' THEN now() ELSE NULL END,confirmed_by=CASE WHEN p_to_status='confirmed' THEN p_admin_id ELSE NULL END WHERE id=v.id; INSERT INTO public.event_vendor_assignment_activities(assignment_id,event_type,actor_id,metadata) VALUES(v.id,p_to_status,p_admin_id,jsonb_build_object('from',v.status,'to',p_to_status)); RETURN v.id; END $$;
REVOKE ALL ON FUNCTION public.create_admin_vendor_assignment(UUID,UUID,UUID,NUMERIC,DATE,TEXT,TEXT,UUID),public.update_admin_vendor_assignment(UUID,NUMERIC,DATE,TEXT,TEXT,INTEGER,UUID),public.transition_admin_vendor_assignment(UUID,TEXT,INTEGER,UUID) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.create_admin_vendor_assignment(UUID,UUID,UUID,NUMERIC,DATE,TEXT,TEXT,UUID),public.update_admin_vendor_assignment(UUID,NUMERIC,DATE,TEXT,TEXT,INTEGER,UUID),public.transition_admin_vendor_assignment(UUID,TEXT,INTEGER,UUID) TO service_role;
